"""Validate reviewed observations and render a bounded public catalog. No ingestion."""
import argparse
import datetime
import html
import json
from pathlib import Path
import re
import shutil
from urllib.parse import urlsplit

ROOT = Path(__file__).resolve().parent.parent
SOURCE = ROOT / 'docs/compatibility/reports.json'
TABLE = ROOT / 'docs/compatibility/records.md'
TRACKS = {'rosetta-preview': 'Rosetta Preview', 'rosetta-free-development': 'Rosetta-free development'}
EVIDENCE = {'reported': 'Reported', 'reproduced': 'Independently reproduced', 'qualified': 'Pear qualified'}
RESULTS = {'launch-failed': 'Launch failed', 'launched-unusable': 'Launched, unusable',
           'menu-interactive': 'Interactive menu', 'active-gameplay': 'Active gameplay', 'regression': 'Regression'}
CHECKS = {'input', 'audio', 'save_reload', 'recovery'}
STATES = {'observed', 'failed', 'not-tested'}
TEXT = {'id', 'game', 'app_id', 'tested_on', 'track', 'evidence', 'result', 'pear_version',
        'runtime', 'game_build', 'steam_build', 'host', 'settings', 'summary', 'limitations'}
URLS = {'source_url', 'reproduction_url', 'qualification_url', 'architecture_evidence_url'}


def require(ok, message):
    if not ok:
        raise ValueError(message)


def public_url(value):
    require(isinstance(value, str), 'Evidence links must be HTTPS URLs')
    u = urlsplit(value)
    require(u.scheme == 'https' and u.hostname == 'github.com' and not u.username
            and not u.password and u.port is None and not u.query and not u.fragment
            and u.path.startswith('/postmelee/pear/'), 'Use a reviewed Pear GitHub evidence URL')
    require(not any(c.isspace() or ord(c) < 32 for c in value), 'Invalid evidence URL')
    return value


def validate(data):
    require(isinstance(data, dict) and set(data) == {'schema_version', 'records'}
            and type(data['schema_version']) is int and data['schema_version'] == 1,
            'Expected schema_version 1 and records')
    require(isinstance(data['records'], list), 'records must be a list')
    seen = set()
    for r in data['records']:
        require(isinstance(r, dict) and set(r) == TEXT | URLS | {'play_minutes', 'checks'},
                'Unknown or missing record fields')
        for key in TEXT:
            value = r[key]
            require(isinstance(value, str) and 0 < len(value.strip()) <= 2000
                    and not any(ord(c) < 32 for c in value), f'Invalid text: {key}')
        require(re.fullmatch(r'[a-z0-9]+(?:-[a-z0-9]+)*', r['id']) is not None, 'Invalid record id')
        require(r['id'] not in seen, 'Duplicate record id')
        seen.add(r['id'])
        require(re.fullmatch(r'[1-9][0-9]*', r['app_id']) is not None, 'Invalid Steam App ID')
        require(datetime.date.fromisoformat(r['tested_on']).isoformat() == r['tested_on'], 'Invalid test date')
        require(r['track'] in TRACKS and r['evidence'] in EVIDENCE and r['result'] in RESULTS,
                'Unknown track, evidence or result')
        require(isinstance(r['checks'], dict) and set(r['checks']) == CHECKS
                and all(v in STATES for v in r['checks'].values()), 'Invalid observed checks')
        minutes = r['play_minutes']
        require(minutes is None or (type(minutes) is int and 0 <= minutes <= 100000), 'Invalid play duration')
        if r['result'] == 'active-gameplay':
            require(minutes is not None and minutes > 0, 'Gameplay needs recorded minutes')
        for key in URLS:
            if r[key] is not None:
                public_url(r[key])
        require(r['source_url'] is not None, 'Source evidence is required')
        if r['evidence'] in {'reproduced', 'qualified'}:
            require(r['reproduction_url'] is not None and r['reproduction_url'] != r['source_url'],
                    'Independent reproduction needs separate evidence')
        if r['evidence'] == 'qualified':
            require(r['qualification_url'] is not None and r['result'] == 'active-gameplay'
                    and minutes is not None and minutes >= 20
                    and all(v == 'observed' for v in r['checks'].values()),
                    'Qualification needs an approved record, gameplay and required observations')
            if r['track'] == 'rosetta-free-development':
                require(r['architecture_evidence_url'] is not None, 'Native qualification needs architecture evidence')
    return data


def md(value):
    # User descriptions remain literal text rather than Markdown/HTML instructions.
    value = html.escape(str(value))
    return re.sub(r'([\\`*_{}\[\]()#+.!|~-])', r'\\\1', value)


def markdown(data):
    lines = ['# Reviewed game observations', '',
             '<!-- Generated by tools/compatibility.py; edit reports.json through review. -->', '',
             'These are configuration-specific observations, not a list of universally supported games.',
             'Read the [evidence meanings and reporting guide](README.md). The [Preview download](../rosetta-preview.md) has configuration-specific verification.', '',
             '| Game | Track | Environment | Observation | Evidence | Date |',
             '|---|---|---|---|---|---|']
    for r in data['records']:
        lines.append(f"| {md(r['game'])} ({r['app_id']}) | {TRACKS[r['track']]} | {md(r['host'])} | {RESULTS[r['result']]} | {EVIDENCE[r['evidence']]} | {r['tested_on']} |")
    if not data['records']:
        lines.extend(['', 'No reviewed observations yet.'])
    for r in data['records']:
        lines.extend(['', f"## {md(r['game'])} — {r['tested_on']}", '', f"Record: `{r['id']}`", '',
                      f"{md(r['summary'])}", '', f"**Limits:** {md(r['limitations'])}", '',
                      f"- Pear: {md(r['pear_version'])}", f"- Runtime: {md(r['runtime'])}",
                      f"- Game build: {md(r['game_build'])}; Steam build: {md(r['steam_build'])}",
                      f"- Settings: {md(r['settings'])}",
                      f"- Active gameplay minutes: {r['play_minutes'] if r['play_minutes'] is not None else 'not measured'}",
                      '- Checks: ' + '; '.join(f"{k.replace('_', ' ')}: {r['checks'][k]}" for k in sorted(CHECKS))])
        for key in sorted(URLS):
            if r[key]:
                lines.append(f"- [{key.removesuffix('_url').replace('_', ' ').capitalize()}]({r[key]})")
    return '\n'.join(lines) + '\n'


CATALOG = ROOT / 'docs/compatibility/games.json'
ASSETS = ROOT / 'tools/catalog'
PUBLIC_FILES = {'index.html', 'style.css', 'catalog.js', 'reports.json', 'games.json',
                'pear.png', 'favicon.png', 'steam-search.js', 'report.html', 'request.html', 'about.html', 'download.html'}
OPTIONAL_PUBLIC_FILES = {'steam-games.json'}
OUTCOMES = {'pass': 'Pass', 'partial': 'Partial', 'failed': 'Failed'}


def validate_catalog(catalog, data):
    require(isinstance(catalog, dict) and set(catalog) == {'schema_version', 'github_forms_live', 'games'}
            and type(catalog['schema_version']) is int and catalog['schema_version'] == 1
            and type(catalog['github_forms_live']) is bool and isinstance(catalog['games'], list),
            'Invalid game catalog')
    seen = set()
    for game in catalog['games']:
        require(isinstance(game, dict) and set(game) == {'app_id', 'name', 'image_url', 'image_source_url', 'image_credit', 'request'}, 'Invalid game metadata fields')
        app = game['app_id']
        require(isinstance(app, str) and re.fullmatch(r'[1-9][0-9]*', app) is not None and app not in seen, 'Invalid or duplicate catalog App ID')
        seen.add(app)
        for key in ['name', 'image_credit']:
            require(isinstance(game[key], str) and 0 < len(game[key]) < 500 and not any(ord(c) < 32 for c in game[key]), 'Invalid game text')
        image = game['image_url']
        require((image is None) == (game['image_source_url'] is None), 'Artwork needs its source')
        if image is not None:
            u = urlsplit(image)
            require(u.scheme == 'https' and u.hostname in {'shared.akamai.steamstatic.com', 'shared.fastly.steamstatic.com', 'cdn.akamai.steamstatic.com'}
                    and not u.username and not u.password and u.port is None
                    and u.path.startswith(f'/store_item_assets/steam/apps/{app}/') and u.path.endswith(('.jpg', '.png'))
                    and '..' not in u.path and '%' not in u.path and not u.fragment
                    and (not u.query or re.fullmatch(r't=[0-9]+', u.query)), 'Unreviewed artwork URL')
            source = urlsplit(game['image_source_url'])
            require(source.scheme == 'https' and source.netloc == 'store.steampowered.com'
                    and source.path.startswith(f'/app/{app}/') and not source.query and not source.fragment, 'Invalid artwork source')
        request = game['request']
        require(isinstance(request, dict) and set(request) == {'discussion_url', 'upvotes', 'synced_at'}, 'Invalid demand record')
        if request['discussion_url'] is None:
            require(request['upvotes'] is None and request['synced_at'] is None, 'No vote counts without a canonical request')
        else:
            require(re.fullmatch(r'https://github\.com/postmelee/pear/discussions/[1-9][0-9]*', request['discussion_url']) is not None, 'Invalid request Discussion')
            require((request['upvotes'] is None) == (request['synced_at'] is None), 'Vote snapshot needs a timestamp')
            if request['upvotes'] is not None:
                require(type(request['upvotes']) is int and request['upvotes'] >= 0, 'Invalid vote count')
                require(isinstance(request['synced_at'], str) and datetime.date.fromisoformat(request['synced_at']).isoformat() == request['synced_at'], 'Invalid vote snapshot date')
    require(all(r['app_id'] in seen for r in data['records']), 'Every reported game needs reviewed catalog metadata')
    return catalog


def outcome(record):
    if record['result'] in {'launch-failed', 'launched-unusable', 'regression'} or 'failed' in record['checks'].values():
        return 'failed'
    if (record['result'] == 'active-gameplay' and (record['play_minutes'] or 0) >= 20
            and all(record['checks'][k] == 'observed' for k in ('input', 'audio', 'save_reload'))):
        return 'pass'
    return 'partial'


def group_games(data, catalog):
    groups = []
    for game in catalog['games']:
        records = sorted((r for r in data['records'] if r['app_id'] == game['app_id']), key=lambda r: (r['tested_on'], r['id']), reverse=True)
        groups.append({**game, 'records': records})
    return sorted(groups, key=lambda g: g['name'].casefold())


def counts(records):
    return {key: sum(outcome(r) == key for r in records) for key in OUTCOMES}


def report_counts(records, css='report-counts'):
    return '<div class="' + css + '">' + ''.join(f'<span class="{key}"><b data-count="{key}">{value}</b> {OUTCOMES[key]}</span>' for key, value in counts(records).items()) + '</div>'


def cover(game):
    e = html.escape
    image = f'<img class="game-art" src="{e(game["image_url"], quote=True)}" alt="{e(game["name"], quote=True)} artwork" width="616" height="353" loading="lazy" referrerpolicy="no-referrer">' if game['image_url'] else ''
    return f'<div class="cover"><span class="fallback" aria-hidden="true">{e(game["name"])}</span>{image}</div>'


def demand_link(game):
    return game['request']['discussion_url'] or f'request.html?app={game["app_id"]}'


def demand_label(game):
    votes = game['request']['upvotes']
    if game['request']['discussion_url']:
        return '↑ Vote on GitHub' if votes is None else f'↑ {votes} · Vote on GitHub'
    return '↑ Request support'


def shell(title, content, active='games'):
    e = html.escape
    return f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)} · Pear</title><meta name="description" content="Windows games on Mac. Free and open source. Building a Rosetta-free way to play."><meta name="referrer" content="no-referrer"><link rel="icon" type="image/png" href="favicon.png"><link rel="stylesheet" href="style.css"><script src="steam-search.js" defer></script><script src="catalog.js" defer></script></head>
<body><div class="wrap"><header class="site-header"><a class="brand" href="index.html" aria-label="Pear home"><img src="pear.png" alt="" width="39" height="39">Pear</a><nav aria-label="Main"><a class="{'current' if active=='games' else ''}" href="index.html#games">Games</a><a class="{'current' if active=='download' else ''}" href="download.html">Download</a><a class="{'current' if active=='about' else ''}" href="about.html">About</a><a class="nav-docs" href="https://github.com/postmelee/pear/blob/master/docs/README.md">Docs</a><a class="external nav-github" href="https://github.com/postmelee/pear">GitHub</a></nav></header><main>{content}</main><footer class="site-footer"><span>Pear · Free and open source.</span><div class="footer-links"><a href="about.html#results">How results work</a><a href="reports.json">Open data</a><a class="external" href="https://github.com/postmelee/pear">GitHub</a></div></footer></div></body></html>'''


def game_card(game):
    e = html.escape
    records = game['records']
    latest = records[0] if records else None
    stage = RESULTS[latest['result']] if latest else 'Not tested'
    count = len(records)
    request = game['request']
    href = f'game-{game["app_id"]}.html'
    rows = [{'track': r['track'], 'outcome': outcome(r), 'date': r['tested_on'], 'result': r['result'], 'qualified': r['evidence'] == 'qualified'} for r in records]
    qualified = any(r['evidence'] == 'qualified' for r in records)
    return f'''<article class="game-row" data-game data-name="{e(game['name'], quote=True)}" data-app="{game['app_id']}" data-records="{e(json.dumps(rows), quote=True)}" data-request="{'yes' if request['discussion_url'] else 'no'}" data-votes="{request['upvotes'] if request['upvotes'] is not None else -1}" data-qualified="{'yes' if qualified else 'no'}"><a href="{href}" aria-label="View {e(game['name'], quote=True)} reports">{cover(game)}</a><div><h3><a href="{href}">{e(game['name'])}</a></h3><div class="badges"><span data-stage class="badge {outcome(latest) if latest else ''}">{'Verified configuration' if qualified else e(stage)}</span>{('<span data-runtime class="badge">'+TRACKS[latest['track']]+'</span>') if latest else ''}</div><p class="meta"><span data-report-total>{count} {'report' if count==1 else 'reports'}</span> · <span data-latest>{'Last tested '+latest['tested_on'] if latest else 'No reports yet'}</span></p>{report_counts(records)}</div><div class="row-actions"><a class="button primary small" href="{href}">View game →</a><a class="button small" href="{demand_link(game)}">{demand_label(game)}</a><span class="meta">{'Votes synced '+request['synced_at'] if request['synced_at'] else 'Support requests on GitHub'}</span></div></article>'''


def webpage(data, catalog=None):
    catalog = catalog or json.loads(CATALOG.read_text())
    games = group_games(data, catalog)
    reports = sum(bool(g['records']) for g in games)
    requests = sum(bool(g['request']['discussion_url']) for g in games)
    cards = ''.join(game_card(g) for g in games)
    return shell('Windows games on Mac', f'''<section class="hero"><div><h1>Windows games<br>on Mac.</h1><p class="lead">Free and open source.<br>Building a Rosetta-free way to play.</p><div class="actions"><a class="button primary" href="download.html">Download Pear <span aria-hidden="true">↓</span></a><a class="button quiet" href="#games">Explore games →</a></div></div><div class="hero-art" aria-hidden="true"><img src="pear.png" alt="" width="245" height="245"></div></section><div class="preview-strip"><span class="dot"></span><span><strong>Preview 0.1.0-preview.3</strong> · Available now · Rosetta required</span><a href="about.html#preview">Current status →</a></div><section class="catalog" id="games"><div class="section-top"><div><h2>Find your game</h2><p>Community reports, one Mac at a time.</p></div><a class="text-link" href="report.html">Share a result ↗</a></div><div class="tabs" aria-label="Game lists"><button class="tab" type="button" data-tab="all" aria-pressed="true">All games <span class="count">{len(games)}</span></button><button class="tab" type="button" data-tab="reported" aria-pressed="false">With reports <span class="count">{reports}</span></button><button class="tab" type="button" data-tab="requests" aria-pressed="false">Requests <span class="count">{requests}</span></button></div><div class="toolbar"><label class="search-wrap"><span class="sr-only">Search games</span><input type="search" id="search" placeholder="Search games or Steam App ID" autocomplete="off"></label><label><span class="sr-only">Result filter</span><select id="result-filter"><option value="all">All results</option><option value="pass">Has Pass reports</option><option value="partial">Has Partial reports</option><option value="failed">Has Failed reports</option><option value="qualified">Verified configuration</option><option value="untested">Not tested</option></select></label><label><span class="sr-only">Runtime filter</span><select id="track-filter"><option value="all">All runtimes</option><option value="rosetta-preview">Rosetta Preview</option><option value="rosetta-free-development">Rosetta-free development</option></select></label><label><span class="sr-only">Sort games</span><select id="sort"><option value="recent">Recently tested</option><option value="votes">Most requested</option><option value="reports">Most reports</option><option value="name">Name A–Z</option></select></label></div><div class="list-meta"><span id="result-count" role="status" aria-live="polite">{len(games)} {'game' if len(games)==1 else 'games'}</span><a href="about.html#results">Pass, Partial & Failed ⓘ</a></div><noscript><p class="no-js">All games are shown. Enable JavaScript to search, filter and sort.</p></noscript><div class="game-list">{cards}</div><div class="empty-state" id="no-results" hidden><h3 id="empty-heading">No games found</h3><p id="empty-copy">Try a different search or filter.</p><button class="button small" type="button" id="reset-filters">Clear filters</button><a class="button small" href="request.html">Request a game</a></div><div class="contribute-strip"><div><h3>Your game could be next.</h3><p>Request a game, vote for support, or share what worked.</p></div><a class="button" href="request.html">Request a game <span aria-hidden="true">↗</span></a></div></section>''')


def report_card(r):
    e = html.escape
    result = outcome(r)
    minutes = f"{r['play_minutes']} min" if r['play_minutes'] is not None else 'Not measured'
    states = {'observed': 'Observed', 'failed': 'Failed', 'not-tested': 'Not tested'}
    checks = [('Furthest result', RESULTS[r['result']]), ('Active play', minutes)]
    checks += [(label, states[r['checks'][key]]) for key, label in
               [('input', 'Input'), ('audio', 'Audio'), ('save_reload', 'Save / reload'), ('recovery', 'Recovery')]]
    fields = [('Pear', r['pear_version']), ('Runtime', r['runtime']), ('Game build', r['game_build']),
              ('Steam build', r['steam_build']), ('Settings', r['settings']),
              ('Evidence', EVIDENCE[r['evidence']]),
              ('Independent reproduction', 'Linked record' if r['reproduction_url'] else 'Not recorded'),
              ('Pear qualification', 'Qualified' if r['evidence'] == 'qualified' else 'Not qualified'),
              ('Test notes', r['limitations'])]
    links = ' · '.join(f'<a class="source external" href="{e(r[key], quote=True)}">{key.removesuffix("_url").replace("_", " ").capitalize()}</a>' for key in sorted(URLS) if r[key])
    return f'''<article class="report" data-report data-track="{r['track']}" data-outcome="{result}" id="{r['id']}">
<div class="report-head"><h3>{e(r['host'])}</h3><time class="meta" datetime="{r['tested_on']}">{r['tested_on']}</time></div>
<div class="badges"><span class="badge {result}">{OUTCOMES[result]}</span><span class="badge">{TRACKS[r['track']]}</span><span class="badge">{EVIDENCE[r['evidence']]}</span></div>
<p>{e(r['summary'])}</p><dl class="test-checks">{''.join(f'<div><dt>{e(k)}</dt><dd>{e(v)}</dd></div>' for k,v in checks)}</dl>
<details><summary>Versions &amp; test details</summary><dl class="facts">{''.join(f'<dt>{e(k)}</dt><dd>{e(v)}</dd>' for k,v in fields)}</dl><p>{links}</p></details></article>'''


def game_page(game):
    e = html.escape
    records = game['records']
    qualified = any(r['evidence']=='qualified' for r in records)
    request = game['request']
    vote_text = str(request['upvotes']) if request['upvotes'] is not None else '—'
    votes = f'<p class="big-number">{vote_text}</p><p>{"votes · synced "+request["synced_at"] if request["synced_at"] else "Vote count unavailable"}</p>' if request['discussion_url'] else '<p>No support request yet. Start the conversation on GitHub.</p>'
    cards = ''.join(report_card(r) for r in records)
    return shell(game['name'], f'''<p class="crumb"><a href="index.html#games">← All games</a></p><section class="detail-hero">{cover(game)}<div><h1>{e(game['name'])}</h1><p class="meta">Steam App {game['app_id']}</p><div class="badges"><span class="badge {'pass' if qualified else 'partial'}">{'Verified configuration' if qualified else 'Community reports' if records else 'Not tested'}</span></div><div class="actions"><a class="button" href="https://store.steampowered.com/app/{game['app_id']}/" rel="noreferrer">View on Steam ↗</a><a class="button primary" href="report.html?app={game['app_id']}">Share a result</a></div></div></section><div class="detail-layout"><section><div class="detail-section-head"><h2>Player reports <span class="meta">{len(records)}</span></h2><div class="report-filters"><label><span class="sr-only">Filter report runtime</span><select id="report-track"><option value="all">All runtimes</option><option value="rosetta-preview">Rosetta Preview</option><option value="rosetta-free-development">Rosetta-free development</option></select></label><label><span class="sr-only">Filter report result</span><select id="report-result"><option value="all">All results</option><option value="pass">Pass</option><option value="partial">Partial</option><option value="failed">Failed</option></select></label></div></div>{report_counts(records)}<p class="meta" style="margin:12px 0 18px">Reports describe individual configurations. They are not votes or unique-player counts.</p><div id="reports">{cards}</div><div class="empty-state" id="no-reports" {'hidden' if records else ''}><h3>No reports for this selection</h3><p>Change the filters or share your own result.</p><a class="button small" href="report.html?app={game['app_id']}">Share a result</a></div><p class="art-credit">{e(game['image_credit'])} <a class="inline-link" href="{e(game['image_source_url'] or 'https://store.steampowered.com/app/'+game['app_id']+'/')}">Source</a></p></section><aside><div class="aside-card"><h2>Want better support?</h2>{votes}<a class="button" href="{demand_link(game)}">{demand_label(game)}</a><p>Votes show demand. Test reports show what happened.</p></div><div class="aside-card"><h2>Know before you play</h2><ul><li>Current Preview requires Rosetta.</li><li><a href="download.html">Download the Preview</a>.</li><li>Check the version and Mac in each report.</li></ul><a class="text-link" href="about.html#results">How results work →</a></div></aside></div>''')


def about_page():
    return shell('About', '''<div class="readable"><h1>A simpler way to play.</h1><p>Pear is a free, open-source project bringing Windows Steam games to Apple Silicon. Open Pear, sign in through official Steam, and choose a game from your library.</p><p>Our goal is an experience without Rosetta in every required process and library. That native runtime is still in development.</p><h2 id="preview">Meet the Preview</h2><p>The current Preview uses Rosetta, Wine 11.0 and DXMT 0.80. It targets Apple Silicon and macOS 26+, with local observations on M4 Pro / macOS 26.5.2.</p><div class="notice">Preview.3 is available. Megabonk play, save/relaunch, recovery and a fresh standard-user installation were checked on the same M4 Pro. Other Macs and games remain unverified.</div><p>You should not need to learn Wine or use Terminal for routine play. An optional CLI shares the same setup as the app.</p><div class="actions"><a class="button primary external" href="https://github.com/postmelee/pear/discussions/51">Preview updates</a><a class="button external" href="https://github.com/postmelee/pear/blob/master/docs/delivery-plan.md">Roadmap</a></div><h2 id="results">Reading game results</h2><table class="explain-table"><thead><tr><th>Result</th><th>What it means</th></tr></thead><tbody><tr><td><span class="badge pass">Pass</span></td><td>A report records at least 20 active play minutes, input, audio and save/reload, with no failed checks. It is still a community observation.</td></tr><tr><td><span class="badge partial">Partial</span></td><td>Some progress was observed, but the full play checks are incomplete. Menu-only observations belong here.</td></tr><tr><td><span class="badge failed">Failed</span></td><td>A launch failure, unusable game, regression or failed check was reported. Read the details for its scope.</td></tr></tbody></table><p>A <strong>verified configuration</strong> also requires a reviewed Pear acceptance record. A Pass report or a popular request does not grant that status. Native qualification needs process and library evidence as well.</p><p>Reports from different Macs, runtimes and dates can disagree. Use the filters and inspect their details. Counts refer to records, not unique players or a universal success rate.</p><h2 id="requests">One community, on GitHub</h2><p>Game requests, upvotes and original reports live on GitHub. Pear groups reviewed records by Steam App ID. Votes express interest; maintainers also consider reproducibility, effort and benefits to other games.</p><p>Vote counts, when available, are dated GitHub snapshots. A missing count stays unavailable. No separate Pear account or voting database is needed.</p><h2>Help build what comes next.</h2><p>Contribute to the current Preview, the Rosetta-free runtime, documentation or game testing. You do not need paid AI tools to take part.</p><div class="actions"><a class="button external" href="https://github.com/postmelee/pear/discussions/53">Rosetta-free development</a><a class="button external" href="https://github.com/postmelee/pear/blob/master/docs/contributing.md">Contributing</a></div></div>''', 'about')


def intake_page(catalog, kind, steam_available=False):
    report = kind == 'report'
    name = 'Share a result' if report else 'Request a game'
    e = html.escape
    identities = e(json.dumps([{'app_id': g['app_id'], 'name': g['name']} for g in catalog['games']]), quote=True)
    common = f'''<fieldset class="game-picker" data-games="{identities}" data-steam-index="{'steam-games.json' if steam_available else ''}"><legend>Choose a game</legend>
<div class="field steam-search-field"><label for="steam-search">Search Steam games</label><div class="steam-combobox"><input type="search" id="steam-search" maxlength="200" autocomplete="off" spellcheck="false" role="combobox" aria-autocomplete="list" aria-expanded="false" aria-controls="steam-results" aria-describedby="steam-search-status" placeholder="Game name or App ID"><ul id="steam-results" role="listbox" aria-label="Steam games" hidden></ul></div><small id="steam-search-status" role="status" aria-live="polite">Search by name, or paste a Steam link below.</small><button id="retry-steam-search" type="button" class="text-link" hidden>Try loading again</button></div>
<div class="field"><label for="steam-identity">Steam store link or App ID</label><input id="steam-identity" name="steam_identity" maxlength="300" required autocomplete="off" spellcheck="false" placeholder="https://store.steampowered.com/app/3405340/"><small id="identity-status" role="status" aria-live="polite">Choose a search result, or paste its Steam store link.</small></div>
<input type="hidden" id="app-id" name="app"><div class="field game-name-field"><label for="game-name">Game name</label><div class="selected-game"><input id="game-name" name="game" readonly placeholder="Filled from the selected Steam App ID"><a id="steam-game-link" class="text-link external" hidden target="_blank" rel="noopener noreferrer">Check on Steam</a></div></div>
</fieldset>'''
    checks_form = '<fieldset class="check-fields"><legend>Test checks</legend><div class="form-grid">' + ''.join(f'<div class="field"><label for="check-{key}">{label}</label><select id="check-{key}" name="{key}"><option>Not tested</option><option>Observed</option><option>Failed</option></select></div>' for key,label in [('input','Input'),('audio','Audio'),('save_reload','Save / reload'),('recovery','Recovery')]) + '</div></fieldset>'
    report_fields = f'''<div class="form-grid"><div class="field"><label for="tested-on">Test date</label><input type="date" id="tested-on" name="date" required></div><div class="field"><label for="runtime">Runtime</label><select id="runtime" name="track" required><option value="">Choose a runtime</option><option>Rosetta Preview</option><option>Rosetta-free development</option><option>Unknown</option></select></div></div><div class="field"><label for="environment">Mac & macOS</label><input id="environment" name="environment" maxlength="200" placeholder="For example: M4 Pro, 24 GB, macOS 26.5.2" required></div><div class="field"><label for="versions">Pear, runtime & game versions</label><input id="versions" name="versions" maxlength="400" placeholder="Write unknown for anything you cannot find" required></div><div class="form-grid"><div class="field"><label for="result">Furthest result</label><select id="result" name="result" required><option value="">Choose a result</option><option>Failed before launch</option><option>Launched but unusable</option><option>Menu visible and interactive</option><option>Active gameplay</option><option>Regression</option></select></div><div class="field"><label for="duration">Active play minutes</label><input id="duration" name="minutes" type="number" min="0" max="100000" step="1" placeholder="Leave blank if not measured"></div></div>{checks_form}<div class="field"><label for="settings">Game settings</label><input id="settings" name="settings" maxlength="600" placeholder="Resolution, graphics preset, or Not recorded"></div><div class="field"><label for="steps">Steps and observations</label><textarea id="steps" name="steps" maxlength="2200" required placeholder="What you did, what happened, and any sanitized error."></textarea></div>'''
    request_fields = '''<div class="field"><label for="reason">What would you like to do?</label><textarea id="reason" name="reason" maxlength="1800" required placeholder="Tell us why you want support, and whether you have tried the game."></textarea></div><p class="meta">Search existing requests on GitHub first. Upvote the existing game discussion when one is available.</p>'''
    notice = '<div class="notice">The GitHub report form is not live yet. Prepare a draft here, copy it, then paste it into a new GitHub discussion. Nothing is submitted automatically.</div>' if report and not catalog['github_forms_live'] else '<p>Your draft stays in this page until you choose to copy it. Continue on GitHub to submit.</p>'
    category = 'show-and-tell' if report else 'ideas'
    live = f'<p><a class="button external" href="https://github.com/postmelee/pear/discussions/new?category={category}">Use the GitHub form</a></p>' if report and catalog['github_forms_live'] else ''
    intro = 'Share what happened on your Mac. Short runs and failures are useful too.' if report else 'Tell the community what you want to play. Requests and votes stay together on GitHub.'
    return shell(name, f'''<div class="readable"><p class="crumb"><a href="index.html#games">← Back to games</a></p><h1>{name}.</h1><p>{intro}</p>{notice}{live}<noscript><p class="no-js">Enable JavaScript to prepare a local draft, or <a class="inline-link" href="https://github.com/postmelee/pear/discussions/new?category={category}">write directly on GitHub</a>.</p></noscript><form id="intake" data-kind="{kind}">{common}{report_fields if report else request_fields}<label class="check-line"><input type="checkbox" name="privacy" required><span>{'I used a legitimately owned game. ' if report else 'I checked existing requests. '}I have removed account details, passwords, QR codes, private logs, saves and game files.</span></label><button class="button primary" type="submit">Prepare GitHub draft →</button></form><section id="draft" class="draft" hidden><h2>Ready for GitHub</h2><p>Copy the title and use the draft below to fill the fields on GitHub. This does not submit or store anything in Pear.</p><div class="field"><label for="draft-title">Discussion title</label><input id="draft-title" readonly></div><label for="draft-body" class="sr-only">Discussion body</label><textarea id="draft-body" readonly></textarea><div class="actions"><button class="button" id="copy-title" type="button">Copy title</button><button class="button primary" id="copy-body" type="button">Copy body</button><a class="button external" id="github-handoff" href="https://github.com/postmelee/pear/discussions/new?category={category}" target="_blank" rel="noopener noreferrer">Open GitHub</a></div><p class="copy-status" id="copy-status" role="status" aria-live="polite"></p></section></div>''', '')


